<CustomerLayout
  title="Booking Policy"
  activePage=""
  description="Soul Pilates cancellation, reschedule, and no-show policies."
>
  <div class="sp-content sp-policy-page">
    <header class="sp-policy-header">
      <h1 class="sp-heading-page">Booking Policy</h1>
      <p class="sp-text-body sp-text-muted" id="policySubtitle">
        Transparent policies to ensure a fair and seamless experience for all our members.
      </p>
    </header>

    <!-- Dynamic policy values are injected from the API -->
    <div id="policyContent">
      <!-- Cancellation Policy -->
      <section class="sp-policy-card" id="sectionCancel">
        <div class="sp-policy-icon">🗓️</div>
        <h2 class="sp-heading-section">Cancellation Policy</h2>
        <p class="sp-text-body sp-mb-md">
          We understand that plans change. To help us manage our classes efficiently
          and keep spots available for everyone, please cancel within the windows below.
        </p>

        <div class="sp-policy-tiers">
          <!-- Credit -->
          <div class="sp-policy-tier">
            <div class="sp-policy-tier-header">
              <span class="sp-policy-tier-icon">💳</span>
              <h3>Package Credit</h3>
            </div>
            <p class="sp-text-body sp-text-sm sp-text-muted">
              Cancel at least
              <strong id="creditGroupHrs" class="sp-policy-hours">3</strong> hours before a
              <strong>Group</strong> class, or
              <strong id="creditPrivateHrs" class="sp-policy-hours">3</strong> hours before a
              <strong>Private</strong> class.
            </p>
            <div class="sp-policy-consequence">
              <span class="sp-policy-consequence-icon">⚠️</span>
              Late cancellation = your credit will be forfeited.
            </div>
          </div>

          <!-- Online -->
          <div class="sp-policy-tier">
            <div class="sp-policy-tier-header">
              <span class="sp-policy-tier-icon">🌐</span>
              <h3>Online Payment (Stripe)</h3>
            </div>
            <p class="sp-text-body sp-text-sm sp-text-muted">
              Cancel at least
              <strong id="onlineGroupHrs" class="sp-policy-hours">3</strong> hours before a
              <strong>Group</strong> class, or
              <strong id="onlinePrivateHrs" class="sp-policy-hours">3</strong> hours before a
              <strong>Private</strong> class.
            </p>
            <div class="sp-policy-consequence">
              <span class="sp-policy-consequence-icon">⚠️</span>
              Late cancellation = your payment is non-refundable.
            </div>
          </div>

          <!-- Studio -->
          <div class="sp-policy-tier">
            <div class="sp-policy-tier-header">
              <span class="sp-policy-tier-icon">🏢</span>
              <h3>Pay at Studio</h3>
            </div>
            <p class="sp-text-body sp-text-sm sp-text-muted">
              Cancel at least
              <strong id="studioGroupHrs" class="sp-policy-hours">3</strong> hours before a
              <strong>Group</strong> class, or
              <strong id="studioPrivateHrs" class="sp-policy-hours">3</strong> hours before a
              <strong>Private</strong> class.
            </p>
            <div class="sp-policy-consequence">
              <span class="sp-policy-consequence-icon">⚠️</span>
              Late cancellation = booking counted as completed.
            </div>
          </div>
        </div>
      </section>

      <!-- Reschedule Policy -->
      <section class="sp-policy-card" id="sectionReschedule">
        <div class="sp-policy-icon">🔄</div>
        <h2 class="sp-heading-section">Reschedule Policy</h2>
        <p class="sp-text-body sp-mb-md" id="rescheduleDescription">
          If you're within the late-cancel window, you may have the option to
          <strong>reschedule</strong> your booking to a different class instead
          of forfeiting your credit or payment.
        </p>
        <ul class="sp-policy-rules" id="rescheduleRules">
          <li>
            <strong id="rescheduleMaxLabel">1</strong> reschedule per month per account.
          </li>
          <li>No refunds — your original credit/payment carries over to the new class.</li>
          <li>The new class must be the same format (Group → Group, Private → Private).</li>
          <li>The new class must have available spots.</li>
        </ul>
        <div class="sp-policy-note" id="rescheduleDisabledNote" style="display:none;">
          <span>ℹ️</span> Late reschedule is currently not available. Please contact the studio for assistance.
        </div>
      </section>

      <!-- No-Show Policy -->
      <section class="sp-policy-card">
        <div class="sp-policy-icon">🚫</div>
        <h2 class="sp-heading-section">No-Show Policy</h2>
        <p class="sp-text-body sp-mb-md">
          If you don't show up to your booked class and haven't cancelled in advance:
        </p>
        <ul class="sp-policy-rules">
          <li>Your booking will be marked as <strong>No-Show</strong>.</li>
          <li>Package credits will be consumed as if you attended.</li>
          <li>Online payments are non-refundable.</li>
          <li>Repeated no-shows may affect your ability to book in the future.</li>
        </ul>
      </section>

      <!-- General -->
      <section class="sp-policy-card">
        <div class="sp-policy-icon">💡</div>
        <h2 class="sp-heading-section">Good to Know</h2>
        <ul class="sp-policy-rules">
          <li>All times are calculated based on the class start time.</li>
          <li>You can view your upcoming bookings and cancel from <a href="/my-bookings">My Bookings</a>.</li>
          <li>If you have any questions, please contact our team at the studio.</li>
          <li>Policies are subject to change — we'll always notify you of any updates.</li>
        </ul>
      </section>
    </div>
  </div>

  <style is:global>
    .sp-policy-page {
      max-width: 680px;
      padding-bottom: 80px;
    }

    .sp-policy-header {
      margin-bottom: 24px;
    }
    .sp-policy-header h1 {
      margin-bottom: 4px;
    }

    .sp-policy-card {
      background: var(--sp-surface, #fff);
      border: 1px solid var(--sp-border, #e5e7eb);
      border-radius: 14px;
      padding: 24px;
      margin-bottom: 16px;
      position: relative;
    }
    [data-theme="dark"] .sp-policy-card {
      background: var(--sp-surface-raised, #1e1e2e);
      border-color: var(--sp-border, #2e2e3e);
    }

    .sp-policy-icon {
      font-size: 28px;
      margin-bottom: 8px;
    }

    .sp-policy-card h2 {
      font-size: 17px;
      font-weight: 700;
      margin-bottom: 8px;
    }

    /* Tier layout */
    .sp-policy-tiers {
      display: flex;
      flex-direction: column;
      gap: 14px;
    }
    .sp-policy-tier {
      background: var(--sp-surface-raised, #f9fafb);
      border: 1px solid var(--sp-border-subtle, #f0f0f0);
      border-radius: 10px;
      padding: 16px;
    }
    [data-theme="dark"] .sp-policy-tier {
      background: var(--sp-surface, #161622);
      border-color: var(--sp-border, #2e2e3e);
    }
    .sp-policy-tier-header {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 8px;
    }
    .sp-policy-tier-header h3 {
      font-size: 14px;
      font-weight: 600;
      margin: 0;
    }
    .sp-policy-tier-icon {
      font-size: 20px;
    }
    .sp-policy-hours {
      color: var(--sp-primary, #8b5cf6);
      font-weight: 700;
    }
    .sp-policy-consequence {
      display: flex;
      align-items: flex-start;
      gap: 6px;
      margin-top: 10px;
      padding: 8px 10px;
      font-size: 12px;
      font-weight: 500;
      color: var(--sp-warning-text, #92400e);
      background: var(--sp-warning-bg, #fffbeb);
      border-radius: 8px;
    }
    [data-theme="dark"] .sp-policy-consequence {
      color: #fbbf24;
      background: rgba(251, 191, 36, 0.08);
    }
    .sp-policy-consequence-icon {
      flex-shrink: 0;
    }

    /* Rules list */
    .sp-policy-rules {
      list-style: none;
      padding: 0;
      margin: 0;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .sp-policy-rules li {
      position: relative;
      padding-left: 20px;
      font-size: 13px;
      line-height: 1.5;
      color: var(--sp-text-secondary, #6b7280);
    }
    .sp-policy-rules li::before {
      content: "•";
      position: absolute;
      left: 6px;
      color: var(--sp-primary, #8b5cf6);
      font-weight: 700;
    }
    .sp-policy-rules a {
      color: var(--sp-primary, #8b5cf6);
      text-decoration: none;
      font-weight: 500;
    }
    .sp-policy-rules a:hover {
      text-decoration: underline;
    }

    .sp-policy-note {
      display: flex;
      align-items: flex-start;
      gap: 8px;
      padding: 10px 12px;
      font-size: 13px;
      color: var(--sp-text-muted, #9ca3af);
      background: var(--sp-surface-raised, #f9fafb);
      border-radius: 8px;
      margin-top: 12px;
    }
    [data-theme="dark"] .sp-policy-note {
      background: var(--sp-surface, #161622);
    }
  </style>
</CustomerLayout>

<script>
  const API = import.meta.env.PUBLIC_API_URL;

  fetch(`${API}/api/customer/cancel-policy`)
    .then((r) => (r.ok ? r.json() : null))
    .then((p) => {
      if (!p) return;

      // Populate cancel windows
      const set = (id, val) => {
        const el = document.getElementById(id);
        if (el) el.textContent = val;
      };
      set("creditGroupHrs", p.cancelWindowHoursCreditGroup ?? 3);
      set("creditPrivateHrs", p.cancelWindowHoursCreditPrivate ?? 3);
      set("onlineGroupHrs", p.cancelWindowHoursOnlineGroup ?? 3);
      set("onlinePrivateHrs", p.cancelWindowHoursOnlinePrivate ?? 3);
      set("studioGroupHrs", p.cancelWindowHoursStudioGroup ?? 3);
      set("studioPrivateHrs", p.cancelWindowHoursStudioPrivate ?? 3);

      // Reschedule section
      if (!p.enableLateReschedule) {
        document.getElementById("rescheduleRules").style.display = "none";
        document.getElementById("rescheduleDisabledNote").style.display = "";
      } else {
        const max = p.lateRescheduleMaxPerMonth ?? 1;
        const mode = p.lateRescheduleMode === "BOOKING" ? "per booking" : "per month per account";
        set("rescheduleMaxLabel", max);
        const ruleEl = document.querySelector("#rescheduleRules li:first-child");
        if (ruleEl)
          ruleEl.innerHTML = `<strong>${max}</strong> reschedule ${mode}.`;
      }
    })
    .catch(() => {});
</script>

<script>
  // GA4 — Policy page engagement tracking
  if (typeof window.spTrackEvent === 'function') {
    window.spTrackEvent('page_view_custom', { page: 'booking_policy' });
  }

  // Track scroll depth on policy page (user reading the full policy)
  const policyMilestones = { 50: false, 100: false };
  window.addEventListener('scroll', function() {
    const pct = Math.round((window.scrollY / (document.body.scrollHeight - window.innerHeight)) * 100);
    [50, 100].forEach(m => {
      if (pct >= m && !policyMilestones[m]) {
        policyMilestones[m] = true;
        if (typeof window.spTrackEvent === 'function') {
          window.spTrackEvent('scroll_depth', { percent: m, page: 'booking_policy' });
        }
      }
    });
  }, { passive: true });
</script>

