using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;
using System;

namespace SoulPilates.Core.Entities;

public class CustomerAccount : BaseEntity
{
    public string FullName { get; set; } = null!;
    public string Email { get; set; } = null!;
    public string PasswordHash { get; set; } = null!;
    public string? PhoneNumber { get; set; }
    public string? CountryOfOrigin { get; set; } = "Vietnam";

    /// <summary>Linked CRM Client record — populated on register via phone/email match.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? ClientId { get; set; }

    // ── Federated identity (Google Sign-in / Sign-up) ──
    /// <summary>
    /// Google's stable subject identifier (the id_token <c>sub</c> claim) once
    /// this account has been linked to a Google identity. Null for pure
    /// password accounts. Matched first on Google sign-in so a later email
    /// change on the Google side still resolves to the same account.
    /// </summary>
    public string? GoogleId { get; set; }

    /// <summary>
    /// How the account can authenticate: <c>"password"</c> (default),
    /// <c>"google"</c> (created via Google, no usable password), or
    /// <c>"password,google"</c> once a password account links Google. Purely
    /// informational — login paths key off <see cref="PasswordHash"/> and
    /// <see cref="GoogleId"/> — but handy for the UI and audits.
    /// </summary>
    public string? AuthProvider { get; set; } = "password";

    // Email verification
    public bool EmailVerified { get; set; } = false;
    public string? EmailVerificationToken { get; set; }
    public DateTime? EmailVerificationExpiry { get; set; }

    // Password reset (future)
    public string? PasswordResetToken { get; set; }
    public DateTime? PasswordResetExpiry { get; set; }

    // ── Customer Booking Portal — Onboarding & Payment ──
    public DateTime? DateOfBirth { get; set; }
    public string? MedicalHistory { get; set; }
    public string? ReferralSource { get; set; }                  // "Instagram", "Friend", "Google", etc.
    public string? StripeCustomerId { get; set; }                // Stripe Customer ID for saved cards
    public bool OnboardingCompleted { get; set; } = false;       // Track post-signup onboarding

    // ── Late Reschedule Grace Tracking ──
    /// <summary>
    /// UTC dates when the customer used their late-reschedule grace.
    /// For <c>ACCOUNT</c> mode: checked against current month to enforce the monthly cap.
    /// Admin can reset this list from the client profile to restore the grace.
    /// </summary>
    public List<DateTime> LateRescheduleUsedDates { get; set; } = new();

    /// <summary>
    /// Attendance IDs that have been rescheduled. For <c>BOOKING</c> mode: each
